WHERE tenant_id = #{tenantId}
    AND material_id = #{materialId}
    AND customer_id IS NOT DISTINCT FROM CAST(#{customerId, jdbcType=BIGINT} AS BIGINT)
    AND trade_type = #{tradeType}
    AND use_at = 'Y'
    AND end_dt = CAST(#{startDt} AS DATE) - 1
    AND price_id != #{priceId}
LIMIT 1
